### Python

```python
import sys


# 计算每个字符消失的轮次
def get_rounds(s):
    n = len(s)
    depth = [0] * n

    current_depth = 0
    max_depth = 0

    # 统计每个字符所属括号对的深度
    for i in range(n):
        if s[i] == '(':
            current_depth += 1
            depth[i] = current_depth
            max_depth = max(max_depth, current_depth)
        else:
            depth[i] = current_depth
            current_depth -= 1

    # 根据最大深度计算消失轮次
    for i in range(n):
        depth[i] = max_depth - depth[i] + 1

    return depth


def main():
    data = sys.stdin.read().split()
    t = int(data[0])
    index = 1
    output = []

    for _ in range(t):
        n = int(data[index])
        s = data[index + 1]
        index += 2

        answer = get_rounds(s)
        output.append(' '.join(map(str, answer)))

    print('\n'.join(output))


if __name__ == '__main__':
    main()
```

