#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

// 计算每个字符消失的轮次
vector<int> getRounds(const string& s) {
    int n = (int)s.size();
    vector<int> depth(n);

    int currentDepth = 0;
    int maxDepth = 0;

    // 统计每个字符所属括号对的深度
    for (int i = 0; i < n; i++) {
        if (s[i] == '(') {
            currentDepth++;
            depth[i] = currentDepth;
            maxDepth = max(maxDepth, currentDepth);
        } else {
            depth[i] = currentDepth;
            currentDepth--;
        }
    }

    // 根据最大深度计算消失轮次
    for (int i = 0; i < n; i++) {
        depth[i] = maxDepth - depth[i] + 1;
    }

    return depth;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--) {
        int n;
        string s;
        cin >> n >> s;

        vector<int> answer = getRounds(s);

        for (int i = 0; i < n; i++) {
            if (i > 0) {
                cout << ' ';
            }
            cout << answer[i];
        }
        cout << '\n';
    }

    return 0;
}
